uint32_t crc = 0xffffffffu;
while (n >= 8) {
    uint64_t chunk;
    std::memcpy(&chunk, data, 8);
    crc = std::crc32c(crc, chunk);
    data += 8;
    n -= 8;
}
if (n > 0) {
    uint64_t chunk = 0;
    std::memcpy(&chunk, data, n);
    crc = std::crc32c(crc, chunk);
}
return crc ^ 0xffffffffu;

